"""Isolate one coupling family at a time in a native shell/solid assembly."""
from probe_aircraft_a47 import ROOT,RUNTIME,CAND,BINARY,WHOLE,read,dump,rel,now,streamsha,harness,sections,ii,ff,group,env,win_execute
from run_aircraft_a23 import brick_grid,prop
import probe_aircraft_a45 as launcher
from pathlib import Path
import argparse,shutil,json,re,numpy as np
OUT=ROOT/'wtc1_simulation_v8/output/aircraft_a48'
CFG=ROOT/'wtc1_simulation_v8/data/aircraft_a48_predeclaration.json'
CASES=['UNCOUPLED','TYPE2_SPOT5','RBE2_TRANSLATION','RBE3_INTERPOLATION']

def guard():assert streamsha(CFG)==read(OUT/'declaration_guard.json')['sha256'];launcher.guard()

def declare():
 assert not OUT.exists() and not CFG.exists();h=harness();assert h['Status']=='PASS' and h['CurrentIteration']=='AIRCRAFT-A47';previous=ROOT/'wtc1_simulation_v8/output/aircraft_a47';assert read(previous/'publication_verification.json')['pass'];assert read(ROOT/'harness/publication_cycle.json')['pending_count']==0;OUT.mkdir();dump(OUT/'harness_before.json',h)
 for n in ['state.json','publication_cycle.json','experiments/registry.jsonl']:shutil.copy2(ROOT/'harness'/n,OUT/('before_'+Path(n).name))
 patch=read(ROOT/'wtc1_simulation_v8/data/aircraft_a46_predeclaration.json')['patch'];center=np.asarray(patch['coordinates_mm']).mean(axis=0);lo=[-50,center[1]-10,center[2]-10];hi=[-40,center[1]+10,center[2]+10];X,B,m,left,right=brick_grid([1,1,1],lo,hi,first=10);c={'created_utc':now(),'iteration':'AIRCRAFT-A48','seed':1102073,'random_draws':0,'purpose':'Native CHECK of identical shell/solid geometry with no coupling then one TYPE2, RBE2 or RBE3 family. Locate whole sparse-shell assembly failure without changing full impact physics.','units':['g','mm','ms'],'cases':CASES,'facade_patch':patch,'solid':{'coordinates_mm':X.tolist(),'bricks':B,'nodal_masses_g':m.tolist(),'left_node_ids':left,'right_node_ids':right,'expected_mass_g':float(m.sum()),'material_section':'MAT/LAW2/1 from whole A20','property':'TYPE14/1 Isolid14 Ismstr4 Icpre2 Iframe2, cached A41 full-integration reference','scope':'Declared small metal cube coupling instrument, not the full composite core geometry or mass budget.'},'expected_total_mass_g':patch['expected_mass_g']+float(m.sum()),'boundary_conditions':'None; zero initial velocity and no external load. CHECK mechanical free-mode/loading warnings are recorded, not hidden.','constraints':{'TYPE2_SPOT5':'Secondary four left solid nodes, main unchanged four facade facets; exact cached Spot5 numerical options.','RBE2_TRANSLATION':'Facade center node5 references solid left nodes with translational111 rotational000 selection, same original whole syntax.','RBE3_INTERPOLATION':'Solid node10 references nine facade nodes with original whole111/000, Iform2, uniform unit weights. Mass redistribution must be assessed over both bodies together.'},'acceptance':{'Starter_errors':0,'Starter_warnings':0,'native_exit':0,'NORMAL':True,'CHECK_report_BEGIN_END':True,'mass_relative':1e-6,'added_mass_relative':1e-9,'clean_mechanical_CHECK_not_inferred':True},'execution':{'Starter_CPU_threads':1,'Engine_CPU_threads':1,'GPU':False,'per_process_cap_s':180,'expected_total_s':45,'maximum_total_s':1800,'new_installation_or_compilation':False},'sources':[{'path':rel(WHOLE),'sha256':streamsha(WHOLE)},{'path':rel(BINARY),'sha256':streamsha(BINARY)},{'path':rel(previous/'loaded_shell_review.json'),'sha256':streamsha(previous/'loaded_shell_review.json')}],'conditional_whole_ablation':{'case':'WHOLE_NO_RBE3_CHECK','only_after_small_controls_reviewed':True,'purpose':'Diagnostic-only remove RBE3 definitions as a single-family ablation; original node coordinates/materials/elements/masses/groups/TYPE25/TYPE2/RBE2 retained. It is not an impact candidate and changes constraints/mass redistribution explicitly.','fresh_Starter':True,'native_CHECK_only':True,'mass_and_added_mass_must_be_audited':True,'inertia_distribution_not_assumed_identical':True,'old_failed_whole_CHECK_not_replayed':True,'new_physical_duration_credit_s':0},'source_assembly_inspection':'ASSEMC_KIJ+0x664 is a vector load while accumulating an off-diagonal shell block. Static offset does not establish runtime index or unique cause.','whole_physical_input_not_modified':True,'whole_time_credit_s':0,'objective1_complete':False}
 dump(CFG,c);dump(OUT/'declaration_guard.json',{'created_utc':now(),'sha256':streamsha(CFG),'before_native':True});pins={r['path']:r for f in ['preservation_before_metadata.json','artifact_manifest.json'] for r in read(previous/f)['files']}
 for f in ['artifact_manifest.json','publication_verification.json']:
  p=previous/f;pins[rel(p)]={'path':rel(p),'bytes':p.stat().st_size,'sha256':streamsha(p)}
 old=[]
 for r in pins.values():
  st=(ROOT/r['path']).stat();assert st.st_size==r['bytes'];old.append({**r,'mtime_ns_before':st.st_mtime_ns})
 dump(OUT/'preservation_before_metadata.json',{'created_utc':now(),'files':old,'method':'Existing immutable hashes retained; before/after metadata audit, not fresh full old-content rehash.','source_archives_not_rescanned':True});dump(OUT/'previous_goal_turn_audit.json',{'created_utc':now(),'classification':'progress','evidence':'A47 registered166, nine Engine processes, loaded shell references and native window limits preserved; A46+A47 publicly verified with both CI passes. Small loaded shell stiffness agrees, changing next action to coupling graph.','same_external_blocker':False});print({'A48_declared':True,'cases':len(CASES),'expected_mass_g':c['expected_total_mass_g']},flush=True)

def check_cards(n):
 return '\n'.join(['/IMPL/RREF/LIMIT',ff(1,1e30),'/IMPL/NONLIN/1','0 123 1e-11 1e-11 1e-11','/IMPL/SOLVER/2',ii(2,0,1)+ff(1e-8),'/IMPL/DTINI',ff(.001),'/IMPL/DYNA/2',ff(.5,.25),'/IMPL/CHECK','/PRINT/-100/100',f'/RUN/{n}/1',ff(.001),'/TFILE/4',ff(.001),'/VERS/2026'])+'\n'

def native_case(d,n,expected_mass):
 en=env();en.update(OMP_NUM_THREADS='1',RAD_HMPP_DOMAINS='1');ok=win_execute(RUNTIME/'starter_win64.exe',['-i',n+'_0000.rad','-np','1'],d,'starter.log',180,en);log=(d/'starter.log').read_text(errors='replace');w=int(re.findall(r'(\d+) WARNING\(S\)',log)[-1]);e=int(re.findall(r'(\d+) ERROR\(S\)',log)[-1]);strict=ok and w==0 and e==0;dump(d/'starter_gate.json',{'created_utc':now(),'warnings':w,'errors':e,'pass':strict,'requested_CPU_threads':1})
 finished=launcher.execute(d,n) if strict else False;txt=(d/'engine.log').read_text(errors='replace') if (d/'engine.log').exists() else '';report=(d/(n+'_0001.out')).read_text(errors='replace') if (d/(n+'_0001.out')).exists() else '';start=(d/(n+'_0000.out')).read_text(errors='replace');m=re.search(r'TOTAL MASS AND MASS CENTER.*?\n\s*([\d.E+\-]+)\s+[\d.E+\-]+\s+[\d.E+\-]+\s+[\d.E+\-]+',start,re.S);mass=float(m.group(1)) if m else None;ad=re.search(r'TOTAL ADDED MASS\s*=\s*([\d.E+\-]+)',start);added=float(ad.group(1)) if ad else None;check_errors=re.search(r'(\d+) ERRORS',txt);check_warnings=re.search(r'(\d+) WARNINGS',txt);checks={'strict_Starter':strict,'Engine_normal_exit0':finished,'CHECK_begin_end':'BEGIN IMPLICIT MODEL CHECKING' in txt and 'END IMPLICIT MODEL CHECKING' in txt,'declared_region_mass':mass is not None and abs(mass-expected_mass)<=1e-6*expected_mass,'no_added_mass':added is not None and abs(added)<=1e-9*expected_mass};row={'created_utc':now(),'case':d.name,'checks':checks,'assembly_and_mass_pass':all(checks.values()),'CHECK_errors':int(check_errors.group(1)) if check_errors else None,'CHECK_warnings':int(check_warnings.group(1)) if check_warnings else None,'Starter_mass_g':mass,'expected_mass_g':expected_mass,'added_mass_g':added,'ASSEMC_KIJ_abort_seen':'assemc_kij_' in txt,'unsupported_TYPE25_warnings':txt.count('INTERFACE TYPE 25 IS NOT AVAILABLE'),'clean_mechanical_qualification':False,'physical_duration_credit_s':0};dump(d/'review.json',row);print(row,flush=True);return row

def run():
 guard();c=read(CFG);sec=sections();patch=c['facade_patch'];mapping={k:i+1 for i,k in enumerate(patch['original_node_ids'])};X=np.vstack([patch['coordinates_mm'],c['solid']['coordinates_mm']]);rows=[]
 for case in CASES:
  d=OUT/case;assert not d.exists();d.mkdir();n='A48_'+case;L=['#RADIOSS STARTER','/BEGIN',n,ii(2026,0),ff('g','mm','ms'),ff('g','mm','ms'),'/TITLE',n,'/ANALY',ii(0)+ff(0)+ii(0),'/SPMD',ii(0,0)+ff(0,1),'/NODE']+[ii(i+1)+ff(*x) for i,x in enumerate(X)]
  for key in ['/MAT/LAW2/3','/PROP/TYPE1/31','/PART/31','/MAT/LAW2/1']:L+=[key]+sec[key]
  L+=['/SHELL/31']+[ii(i+1,*[mapping[k] for k in e[1:]]) for i,e in enumerate(patch['original_elements'])]+prop(1)+['/PART/11','DECLARED_COUPLING_SOLID',ii(1,1,0),'/BRICK/11']+[ii(101+i,*b) for i,b in enumerate(c['solid']['bricks'])]
  if case=='TYPE2_SPOT5':
   L+=group(501,'SOLID_SECONDARY_LEFT',c['solid']['left_node_ids'])+['/SURF/SEG/501','PATCH_MAIN_FACETS']+[ii(i+1,*[mapping[k] for k in e[1:]]) for i,e in enumerate(patch['original_elements'])]+['/INTER/TYPE2/501','DECLARED_SINGLE_FAMILY_SPOT5',ii(501,501,1000,5,0,2,1000,0)+ff(.8),ii(0)+ff(0)+' '*60+ii(2)]
  elif case=='RBE2_TRANSLATION':L+=group(501,'SOLID_SECONDARY_LEFT',c['solid']['left_node_ids'])+['/RBE2/501','DECLARED_SINGLE_FAMILY_RBE2',ii(5)+'   111 000'+ii(0,501,0)]
  elif case=='RBE3_INTERPOLATION':L+=group(501,'FACADE_INTERPOLATION_HOSTS',list(range(1,10)))+['/RBE3/501','DECLARED_SINGLE_FAMILY_RBE3',ii(10)+'   111 000'+ii(1,2,2),ff(1)+'   111 000'+ii(0,501)]
  L+=['/TH/PART/31','GLOBAL_DIAGNOSTIC_BODIES',''.join(f'{v:>10}' for v in ['IE','KE','HE','PW']),ii(31,11),'/END'];(d/(n+'_0000.rad')).write_text('\n'.join(L)+'\n',encoding='utf8');(d/(n+'_0001.rad')).write_text(check_cards(n),encoding='utf8');dump(d/'generation.json',{'created_utc':now(),'name':n,'case':case,'configuration_sha256':streamsha(CFG),'expected_mass_g':c['expected_total_mass_g'],'whole_model_physics_changed':False,'new_physical_time_credit_s':0});rows.append(native_case(d,n,c['expected_total_mass_g']))
 dump(OUT/'coupling_CHECK_review.json',{'created_utc':now(),'cases':rows,'all_assembly_and_mass_pass':all(r['assembly_and_mass_pass'] for r in rows),'whole_impact_qualified':False,'whole_failure_uniquely_identified':False,'no_physical_duration_credit':True})

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('action',choices=['declare','run']);globals()[p.parse_args().action]()
